function decodeXmlText(
  value: string
) {
  return value
    .replace(
      /&lt;/g,
      "<"
    )
    .replace(
      /&gt;/g,
      ">"
    )
    .replace(
      /&amp;/g,
      "&"
    )
    .replace(
      /&quot;/g,
      '"'
    )
    .replace(
      /&#39;/g,
      "'"
    )
    .replace(
      /&nbsp;/g,
      " "
    );
}

function stripTags(
  value: string
) {
  return decodeXmlText(
    value.replace(
      /<[^>]*>/g,
      " "
    )
  )
    .replace(
      /\s+/g,
      " "
    )
    .trim();
}

function normalizeText(
  value: string
) {
  return value
    .replace(
      /\r/g,
      ""
    )
    .replace(
      /\n+/g,
      " "
    )
    .replace(
      /\s+/g,
      " "
    )
    .trim();
}

function getTag(
  xml: string,
  tag: string
) {
  const pattern =
    new RegExp(
      `<${tag}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tag}>`,
      "i"
    );

  const match =
    xml.match(
      pattern
    );

  return match
    ? stripTags(
        match[1]
      )
    : "";
}

function getEntries(
  xml: string
) {
  return (
    xml.match(
      /<entry(?:\s[^>]*)?>[\s\S]*?<\/entry>/gi
    ) ?? []
  );
}

function getLink(
  entry: string
) {
  const match =
    entry.match(
      /<link[^>]+href=["']([^"']+)["'][^>]*\/?>/i
    );

  return (
    match?.[1] ??
    ""
  );
}

async function fetchText(
  url: string,
  revalidate = 300
) {
