function getTrainSection(
  pageText: string,
  lineName: string
) {
  const start =
    pageText.indexOf(
      lineName
    );

  if (
    start < 0
  ) {
    return null;
  }

  let end =
    pageText.length;

  for (
    const otherLine
    of TOKYO_JR_LINES
  ) {
    if (
      otherLine ===
      lineName
    ) {
      continue;
    }

    const index =
      pageText.indexOf(
        otherLine,
        start +
          lineName.length
      );

    if (
      index > start &&
      index < end
    ) {
      end =
        index;
    }
  }

  end =
    Math.min(
      end,
      start + 500
    );

  return pageText.slice(
    start,
    end
  );
}

function findTrainProblem(
  pageText: string,
  lineName: string
) {
  const nearby =
    getTrainSection(
      pageText,
      lineName
    );

  if (
    !nearby
  ) {
    return null;
  }

  const words = [
    "運転見合わせ",
    "一部列車運休",
    "直通運転中止",
    "運転再開見込",
    "運転再開",
    "運休",
    "遅延",
  ];

  const matched =
    words.find(
      (word) =>
        nearby.includes(
          word
        )
    );

  if (
    !matched
  ) {
    return null;
  }

  if (
    nearby.includes(
      "平常運転"
    ) &&
    !nearby.includes(
      "運転見合わせ"
    ) &&
    !nearby.includes(
      "一部列車運休"
    ) &&
    !nearby.includes(
      "直通運転中止"
    ) &&
    !nearby.includes(
      "運転再開見込"
    ) &&
    !nearby.includes(
      "遅延"
    )
  ) {
    return null;
  }

  return {
    status:
      matched,
  };
}

